package es.pulso.music;
import android.app.*;import android.content.*;import android.media.*;import android.media.session.*;import android.os.*;import java.util.*;
public class PlayerService extends Service {
 public static PlayerService instance; public ArrayList<Song> queue=new ArrayList<>(); public int index=-1; public boolean shuffle=false; public int repeat=0; public String error=""; public boolean preparing=false;
 private int playedSeconds=0;private boolean counted=false;private final Handler counterHandler=new Handler();private final Runnable counter=new Runnable(){public void run(){if(playing()&&current()!=null&&!counted){playedSeconds++;if(playedSeconds>=30){String key="plays_"+current().id;android.content.SharedPreferences prefs=getSharedPreferences("music",0);prefs.edit().putInt(key,prefs.getInt(key,0)+1).apply();counted=true;}}counterHandler.postDelayed(this,1000);}};
 private MediaPlayer player; private MediaSession session; private AudioManager audio; private AudioFocusRequest focus; private boolean resumeFocus=false; private final Random random=new Random();
 public final class LocalBinder extends Binder {public PlayerService get(){return PlayerService.this;}} private final IBinder binder=new LocalBinder();
 private final BroadcastReceiver noisy=new BroadcastReceiver(){public void onReceive(Context c,Intent i){pause();}};
 @Override public void onCreate(){super.onCreate();instance=this;counterHandler.postDelayed(counter,1000);audio=(AudioManager)getSystemService(AUDIO_SERVICE);session=new MediaSession(this,"Pulso");session.setCallback(new MediaSession.Callback(){public void onPlay(){resume();}public void onPause(){pause();}public void onSkipToNext(){next(false);}public void onSkipToPrevious(){previous();}public void onSeekTo(long p){seek((int)p);}public void onStop(){pause();}});session.setActive(true);getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("playback","Reproducción",NotificationManager.IMPORTANCE_LOW));registerReceiver(noisy,new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY));focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()).setOnAudioFocusChangeListener(change->{if(change==AudioManager.AUDIOFOCUS_LOSS){resumeFocus=false;pause();}else if(change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT){resumeFocus=playing();pause();}else if(change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK){if(player!=null)player.setVolume(.2f,.2f);}else if(change==AudioManager.AUDIOFOCUS_GAIN){if(player!=null)player.setVolume(1,1);if(resumeFocus){resumeFocus=false;resume();}}}).build();}
 public IBinder onBind(Intent i){return binder;}
 public int onStartCommand(Intent i,int flags,int id){if(i!=null){String a=i.getAction();if("play".equals(a))resume();if("pause".equals(a))pause();if("next".equals(a))next(false);if("prev".equals(a))previous();}return START_NOT_STICKY;}
 public Song current(){return index>=0&&index<queue.size()?queue.get(index):null;}
 public boolean playing(){try{return player!=null&&player.isPlaying();}catch(Exception e){return false;}}
 public int position(){try{return player!=null&&!preparing?player.getCurrentPosition():0;}catch(Exception e){return 0;}}
 public void play(ArrayList<Song> songs,int selected){queue=new ArrayList<>(songs);index=selected;load();}
 private void load(){Song s=current();if(s==null)return;error="";playedSeconds=0;counted=false;preparing=true;startForeground(1,notification());if(player!=null){player.release();}player=new MediaPlayer();try{player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());player.setWakeMode(this,PowerManager.PARTIAL_WAKE_LOCK);player.setDataSource(this,s.uri);player.setOnPreparedListener(p->{preparing=false;resume();});player.setOnCompletionListener(p->next(true));player.setOnErrorListener((p,w,x)->{preparing=false;error="No se puede reproducir este archivo";pause();return true;});player.prepareAsync();session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,s.title).putString(MediaMetadata.METADATA_KEY_ARTIST,s.subtitle()).putLong(MediaMetadata.METADATA_KEY_DURATION,s.duration).build());update();}catch(Exception e){preparing=false;error="No se puede abrir este archivo";pause();}}
 public void resume(){if(player==null||preparing)return;if(audio.requestAudioFocus(focus)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED){try{startForeground(1,notification());player.start();update();}catch(Exception e){error="No se pudo iniciar la reproducción";}}}
 public void pause(){try{if(player!=null&&player.isPlaying())player.pause();}catch(Exception ignored){}update();stopForeground(false);}
 public void toggle(){if(playing())pause();else resume();}
 public void seek(int p){try{if(player!=null&&!preparing)player.seekTo(p);update();}catch(Exception ignored){}}
 public void next(boolean completed){if(queue.isEmpty())return;if(completed&&repeat==1){seek(0);resume();return;}if(shuffle&&queue.size()>1){int n;do{n=random.nextInt(queue.size());}while(n==index);index=n;}else{if(index+1>=queue.size()){if(completed&&repeat==0){pause();seek(0);return;}index=0;}else index++;}load();}
 public void previous(){if(position()>3000){seek(0);return;}if(queue.isEmpty())return;index=(index-1+queue.size())%queue.size();load();}
 private PendingIntent action(String a){Intent i=new Intent(this,PlayerService.class).setAction(a);return PendingIntent.getService(this,a.hashCode(),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 private Notification notification(){Song s=current();PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,"playback").setSmallIcon(es.pulso.music.R.drawable.icon).setContentTitle(s==null?"Pulso":s.title).setContentText(s==null?"Música local":s.subtitle()).setContentIntent(open).setVisibility(Notification.VISIBILITY_PUBLIC).setOnlyAlertOnce(true).setOngoing(playing()).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_previous,"Anterior",action("prev")).build()).addAction(new Notification.Action.Builder(playing()?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play,playing()?"Pausar":"Reproducir",action(playing()?"pause":"play")).build()).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_next,"Siguiente",action("next")).build()).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1,2)).build();}
 private void update(){if(current()==null)return;session.setPlaybackState(new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS|PlaybackState.ACTION_SEEK_TO).setState(playing()?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED,position(),playing()?1:0).build());getSystemService(NotificationManager.class).notify(1,notification());}
 public void onDestroy(){counterHandler.removeCallbacks(counter);instance=null;if(player!=null)player.release();session.release();audio.abandonAudioFocusRequest(focus);unregisterReceiver(noisy);super.onDestroy();}
}
